# unblob extracts files from container formats; it is the firmware extractor
# `rea` drives through `REA_UNBLOB_COMMAND`.
#
# unblob and most of its dependency tree publish prebuilt extension wheels only
# (unblob itself is a PyO3/maturin project; lief, pyperscan, cryptography and lz4
# are compiled too), so this formula installs the published wheels for macOS
# arm64 and CPython 3.14 instead of compiling each dependency from source. The
# wheel it installs is its own source artifact (`using: :nounzip` keeps it
# intact); the dependency wheels are generated by `scripts/bump/unblob.py` from
# PyPI and pinned with SHA-256. Everything outside the markers is maintained by
# hand.
#
# unblob shells out to external extractor tools. The ones Homebrew packages are
# dependencies, including partclone and sasquatch from this tap. `debugfs` lives
# in the keg-only e2fsprogs, so the installed `unblob` is a wrapper that prepends
# e2fsprogs' sbin (and Homebrew's own sbin) to PATH before running the real CLI.
class Unblob < Formula
  include Language::Python::Virtualenv

  desc "Extract files from any kind of container formats"
  homepage "https://unblob.org"
  url "https://files.pythonhosted.org/packages/e7/bf/afe6d513884431111d808af37ee58be29251385d44466bfcf78b0d15bdfc/unblob-26.6.4-cp39-abi3-macosx_11_0_arm64.whl", using: :nounzip
  version "26.6.4"
  sha256 "a2276495ae5ec3ed760af85c4c486711998205bbff97b09bde970b3d007b1476"
  license "MIT"

  depends_on arch: :arm64
  depends_on "e2fsprogs"
  depends_on "erofs-utils"
  depends_on "libmagic"
  depends_on "libyaml"
  depends_on "lz4"
  depends_on "lziprecover"
  depends_on "lzop"
  depends_on "p7zip"
  depends_on "partclone"
  depends_on "python@3.14"
  depends_on "sasquatch"
  depends_on "simg2img"
  depends_on "unar"
  depends_on "zstd"

  # The published wheels keep `@rpath`-relative dylib IDs (for example
  # pyperscan's extension). Homebrew's default relocation rewrites those to
  # absolute paths, which fails inside the wheels' fixed Mach-O header padding;
  # keeping the relative IDs is also what the wheels expect at runtime.
  preserve_rpath

