  # END GENERATED WHEELS

  def install
    venv = virtualenv_create(libexec, "python3.14")
    wheels = buildpath/"wheels"
    wheels.mkpath
    wheels.install buildpath.glob("*.whl")
    # The wheels are downloaded by Homebrew's fetch phase. Read them straight
    # from the cache: `Resource#fetch` would revalidate the cached file over the
    # network, which the build sandbox does not allow.
    resources.each do |resource|
      download = resource.cached_download
      raise "#{resource.name}: wheel is not in the download cache" unless download.exist?

      # Homebrew prefixes cached downloads with their SHA-256; pip needs the
      # original wheel filename.
      filename = download.basename.to_s.sub(/\A\h{64}--/, "")
      wheels.install download => filename
    end
    venv.pip_install_and_link wheels.children

    # `pip_install_and_link` symlinked every console script, unblob itself
    # included. Replace that symlink with a wrapper so unblob finds the tools of
    # the keg-only e2fsprogs (`debugfs` lives in its sbin) and Homebrew's own
    # sbin (`partclone.restore`) regardless of the caller's PATH.
    e2fsprogs = formula_opt_prefix("e2fsprogs")
    wrapper_path = [
      e2fsprogs/"sbin",
      e2fsprogs/"bin",
      HOMEBREW_PREFIX/"sbin",
      HOMEBREW_PREFIX/"bin",
      "${PATH}",
    ].join(":")

    (bin/"unblob").unlink
    (bin/"unblob").write_env_script libexec/"bin/unblob", PATH: wrapper_path
  end

  def caveats
    <<~EOS
      unblob drives external extractor tools; the ones Homebrew packages are
      installed with it. `debugfs` (ext2/3/4) comes from the keg-only
      `e2fsprogs` formula, whose sbin directory is put on PATH by the `unblob`
      wrapper, so it is found out of the box.

      `unblob --show-external-dependencies` lists every tool and whether it
      was found.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/unblob --version")
    assert_match "Usage: unblob", shell_output("#{bin}/unblob --help")
    # Exits 1 unless every extractor, including the keg-only e2fsprogs
    # `debugfs`, is found through the wrapper's PATH.
    assert_match "debugfs", shell_output("#{bin}/unblob --show-external-dependencies")
  end
end
